  /* ================================================================ */
  /* ===== 徒步路线：canonical 编辑器（城市弹窗与详情页共用同一套字段）===== */
  /* ================================================================ */
  let routeEditorCtx=null;  // {cityKey, idx, anchor:'modal'|'detail'}
  // 难度徽章 HTML
  function routeDifficultyBadge\(difficulty\){
    const key=ROUTE_DIFFICULTIES.includes\(difficulty\)?difficulty:'';
    if\(!key\) return '';
    return '<span class="route-difficulty-badge" data-difficulty="'+key+'">'+DIFFICULTY_LABELS[key]+'</span>';
  }
  // 指标行文本：里程 / 爬升 / 最高海拔
  function routeMetricsText\(route\){
    const parts=[];
    if\(route&&route.distanceKm\) parts.push\(route.distanceKm+' km'\);
    if\(route&&route.elevationGain\) parts.push\('爬升 '+route.elevationGain+' m'\);
    if\(route&&route.maxAltitude\) parts.push\('最高 '+route.maxAltitude+' m'\);
    return parts.join\(' · '\);
  }
  // 坐标文本：GCJ-02，未填写返回空串
  function routeCoordText\(route\){
    if\(!route||route.lng==null||route.lat==null\) return '';
    return route.lng.toFixed\(4\)+', '+route.lat.toFixed\(4\);
  }
  // 编辑器保存一条路线字段（两种入口共用，按类型归一）
  async function saveRouteField\(ctx,field,value\){
    const meta=await getCityMeta\(ctx.cityKey\);
    if\(!meta.attractions||!meta.attractions[ctx.idx]\) return null;
    const route=meta.attractions[ctx.idx];
    if\(field==='difficulty'\) route.difficulty=ROUTE_DIFFICULTIES.includes\(value\)?value:'';
    else if\(field==='distanceKm'||field==='elevationGain'||field==='maxAltitude'\) route[field]=toRouteNumber\(value,0\);
    else if\(field==='lng'\) route.lng=toRouteCoord\(value,-180,180\);
    else if\(field==='lat'\) route.lat=toRouteCoord\(value,-90,90\);
    else route[field]=value;
    await saveCityMeta\(meta\);
    refreshRouteViews\(ctx,meta\);
    return meta;
  }
  // 保存后刷新当前入口的视图
  function refreshRouteViews\(ctx,meta\){
    if\(ctx.anchor==='detail'\){
      attDetailMeta=meta;
      renderAttractionDetailList\(meta.attractions||[]\);
    }else{
      renderAttractions\(meta.attractions||[]\);
    }
    renderCityCards\(\);
  }
  // 上传路线照片/视频（同步写入城市主相册）
  async function routeUploadPhotos\(ctx,files\){
    if\(!ctx||!files||!files.length\) return;
    const meta=await getCityMeta\(ctx.cityKey\);
    if\(!meta.attractions||!meta.attractions[ctx.idx]\) return;
    const city=cityPoints.find\(c=>c&&c.cityKey===ctx.cityKey\);
    if\(!city\) return;
    const existing=await getPhotosByCity\(ctx.cityKey\);
    let baseOrder=existing.length?Math.max\(...existing.map\(p=>p.order||0\)\):0;
    let ok=0,fail=0;
    for\(const f of files\){
      try{
        baseOrder+=1;
        await importAttractionMedia\(f,city,meta.attractions[ctx.idx],baseOrder\);
        ok++;
      }catch\(err\){ console.error\(err\); fail++; }
    }
    await saveCityMeta\(meta\);
    // 更新封面背景（若首张照片变化）
    if\(ctx.anchor==='detail'&&!attDetailCoverUrl&&meta.attractions[ctx.idx].photos.length\){
      attDetailCoverUrl=meta.attractions[ctx.idx].photos[0].dataUrl;
      attDetailBg.style.backgroundImage='url\("'+attDetailCoverUrl+'"\)';
    }
    refreshRouteViews\(ctx,meta\);
    openRouteEditor\(ctx.cityKey,ctx.idx,ctx.anchor\);
    if\(ok\) toast\('已上传 '+ok+' 个路线影像'+\(fail?\('，'+fail+' 个失败'\):''\)\);
    else if\(fail\) toast\('上传失败：'+fail+' 个',true\);
  }
  // 删除路线照片
  async function routeDeletePhoto\(ctx,pi\){
    const meta=await getCityMeta\(ctx.cityKey\);
    if\(!meta.attractions||!meta.attractions[ctx.idx]\) return;
    meta.attractions[ctx.idx].photos.splice\(pi,1\);
    await saveCityMeta\(meta\);
    refreshRouteViews\(ctx,meta\);
    openRouteEditor\(ctx.cityKey,ctx.idx,ctx.anchor\);
  }
  // 交换路线照片位置（拖拽排序）
  async function routeSwapPhotos\(ctx,fromPi,toPi\){
    const meta=await getCityMeta\(ctx.cityKey\);
    if\(!meta.attractions||!meta.attractions[ctx.idx]\) return;
    const arr=meta.attractions[ctx.idx].photos||[];
    if\(fromPi<arr.length&&toPi<arr.length&&fromPi!==toPi\){
      [arr[fromPi],arr[toPi]]=[arr[toPi],arr[fromPi]];
      await saveCityMeta\(meta\);
      refreshRouteViews\(ctx,meta\);
      openRouteEditor\(ctx.cityKey,ctx.idx,ctx.anchor\);
    }
  }
  // 编辑器行骨架
  function routeEditorRow\(label\){
    const row=document.createElement\('div'\);
    row.className='att-edit-row';
    const lb=document.createElement\('label'\);
    lb.textContent=label;
    row.appendChild\(lb\);
    return row;
  }
  function routeEditorField\(labelText,input\){
    const field=document.createElement\('div'\);
    field.className='route-edit-field';
    const span=document.createElement\('span'\);
    span.textContent=labelText;
    field.append\(span,input\);
    return field;
  }
  // 打开 canonical 徒步路线编辑器
  // anchor: 'modal' = 城市编辑弹窗内；'detail' = 城市详情浮层内
  function openRouteEditor\(cityKey,idx,anchor\){
    const meta=cityMetaCache.get\(cityKey\);
    const route=meta&&Array.isArray\(meta.attractions\)?meta.attractions[idx]:null;
    if\(!route\) return;
    const ctx={cityKey,idx,anchor:anchor||'detail'};
    routeEditorCtx=ctx;
    attEditPanel.innerHTML='';
    // 标题栏
    const title=document.createElement\('div'\);
    title.className='att-edit-title';
    const titleName=document.createElement\('span'\);
    titleName.textContent=route.name||\('路线 '+\(idx+1\)\);
    const xBtn=document.createElement\('button'\);
    xBtn.className='x'; xBtn.innerHTML='&times;';
    xBtn.addEventListener\('click',closeAttEditPanel\);
    title.append\(titleName,xBtn\);
    attEditPanel.appendChild\(title\);
    // 路线名称
    const nameRow=routeEditorRow\('路线名称'\);
    const nameInput=document.createElement\('input'\);
    nameInput.type='text'; nameInput.value=route.name||'';
    nameInput.placeholder='路线名称（如：虎丘山径）';
    nameInput.addEventListener\('change',async\(\)=>{
      const saved=await saveRouteField\(ctx,'name',nameInput.value\);
      if\(saved\) titleName.textContent=saved.attractions[idx].name||\('路线 '+\(idx+1\)\);
    }\);
    nameRow.appendChild\(nameInput\);
    attEditPanel.appendChild\(nameRow\);
    // 线路难度
    const diffRow=routeEditorRow\('线路难度'\);
    const diffSelect=document.createElement\('select'\);
    const blankOpt=document.createElement\('option'\);
    blankOpt.value=''; blankOpt.textContent='未标注';
    diffSelect.appendChild\(blankOpt\);
    ROUTE_DIFFICULTIES.forEach\(key=>{
      const opt=document.createElement\('option'\);
      opt.value=key; opt.textContent=DIFFICULTY_LABELS[key];
      diffSelect.appendChild\(opt\);
    }\);
    diffSelect.value=ROUTE_DIFFICULTIES.includes\(route.difficulty\)?route.difficulty:'';
    diffSelect.addEventListener\('change',\(\)=>saveRouteField\(ctx,'difficulty',diffSelect.value\)\);
    diffRow.appendChild\(diffSelect\);
    attEditPanel.appendChild\(diffRow\);
    // 里程 / 爬升 / 最高海拔
    const metricRow=routeEditorRow\('路线数据'\);
    const metricGrid=document.createElement\('div'\);
    metricGrid.className='route-edit-grid-inner';
    [
      {key:'distanceKm',label:'里程 \(km\)',step:'0.1',value:route.distanceKm||0},
      {key:'elevationGain',label:'爬升 \(m\)',step:'1',value:route.elevationGain||0},
      {key:'maxAltitude',label:'最高海拔 \(m\)',step:'1',value:route.maxAltitude||0}
    ].forEach\(spec=>{
      const input=document.createElement\('input'\);
      input.type='number'; input.step=spec.step; input.min='0';
      input.value=spec.value;
      input.addEventListener\('change',\(\)=>saveRouteField\(ctx,spec.key,input.value\)\);
      metricGrid.appendChild\(routeEditorField\(spec.label,input\)\);
    }\);
    metricRow.appendChild\(metricGrid\);
    attEditPanel.appendChild\(metricRow\);
    // 经纬度
    const coordRow=routeEditorRow\('坐标'\);
    const coordGrid=document.createElement\('div'\);
    coordGrid.className='route-edit-grid-inner';
    [
      {key:'lng',label:'经度 lng',step:'0.0001',min:'-180',max:'180',value:route.lng},
      {key:'lat',label:'纬度 lat',step:'0.0001',min:'-90',max:'90',value:route.lat}
    ].forEach\(spec=>{
      const input=document.createElement\('input'\);
      input.type='number'; input.step=spec.step; input.min=spec.min; input.max=spec.max;
      input.value=\(spec.value==null?'':spec.value\);
      input.addEventListener\('change',\(\)=>saveRouteField\(ctx,spec.key,input.value\)\);
      coordGrid.appendChild\(routeEditorField\(spec.label,input\)\);
    }\);
    coordRow.appendChild\(coordGrid\);
    const coordHint=document.createElement\('div'\);
    coordHint.className='att-edit-hint';
    coordHint.textContent='坐标系：高德/腾讯地图（GCJ-02）。GPS 原始坐标（WGS-84）会有约 300–800 米偏移。';
    coordRow.appendChild\(coordHint\);
    attEditPanel.appendChild\(coordRow\);
    // 游玩日期
    const dateRow=routeEditorRow\('游玩日期'\);
    const dateInput=document.createElement\('input'\);
    dateInput.type='date'; dateInput.value=route.visitDate||'';
    dateInput.addEventListener\('change',\(\)=>saveRouteField\(ctx,'visitDate',dateInput.value\)\);
    dateRow.appendChild\(dateInput\);
    attEditPanel.appendChild\(dateRow\);
    // 路线备注
    const notesRow=routeEditorRow\('路线备注'\);
    const notesInput=document.createElement\('textarea'\);
    notesInput.value=route.notes||''; notesInput.placeholder='路线备注…';
    notesInput.addEventListener\('change',\(\)=>saveRouteField\(ctx,'notes',notesInput.value\)\);
    notesRow.appendChild\(notesInput\);
    attEditPanel.appendChild\(notesRow\);
    // 照片缩略图 + 上传（支持拖拽交换位置）
    const photoRow=routeEditorRow\('路线照片'\);
    const thumbs=document.createElement\('div'\);
    thumbs.className='att-edit-thumbs';
    let attEditDragSrc=null;  /* 编辑浮层内照片拖拽源 */
    \(route.photos||[]\).forEach\(\(ph,pi\)=>{
      const t=document.createElement\('div'\);
      t.className='att-edit-thumb';
      t.draggable=true;                  /* 允许拖拽交换位置 */
      t.dataset.pi=pi;
      const img=document.createElement\('img'\);
      img.src=ph.dataUrl;
      t.appendChild\(img\);
      if\(ph.kind==='video'\){
        const badge=document.createElement\('span'\);
        badge.className='att-edit-thumb-video-badge';
        badge.innerHTML='<svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>';
        t.appendChild\(badge\);
      }
      const d=document.createElement\('button'\);
      d.className='del'; d.innerHTML='&times;';
      d.addEventListener\('click',e=>{ e.stopPropagation\(\); routeDeletePhoto\(ctx,pi\); }\);
      t.appendChild\(d\);
      // ===== 拖拽交换位置 =====
      t.addEventListener\('dragstart',e=>{
        attEditDragSrc=t;
        t.classList.add\('dragging'\);
        e.dataTransfer.effectAllowed='move';
        e.dataTransfer.setData\('text/plain',String\(pi\)\);
      }\);
      t.addEventListener\('dragend',\(\)=>{
        t.classList.remove\('dragging'\);
        thumbs.querySelectorAll\('.att-edit-thumb'\).forEach\(c=>c.classList.remove\('drag-over'\)\);
      }\);
      t.addEventListener\('dragover',e=>{
        if\(!attEditDragSrc\) return;
        e.preventDefault\(\);
        e.dataTransfer.dropEffect='move';
        if\(t!==attEditDragSrc\) t.classList.add\('drag-over'\);
      }\);
      t.addEventListener\('dragleave',\(\)=>t.classList.remove\('drag-over'\)\);
      t.addEventListener\('drop',async e=>{
        if\(!attEditDragSrc\) return;
        e.preventDefault\(\);
        t.classList.remove\('drag-over'\);
        if\(t===attEditDragSrc\) return;
        /* 交换 photos 数组中两个位置，持久化后重渲染 */
        const fromPi=Number\(attEditDragSrc.dataset.pi\);
        const toPi=Number\(t.dataset.pi\);
        await routeSwapPhotos\(ctx,fromPi,toPi\);
      }\);
      thumbs.appendChild\(t\);
    }\);
    const uploadBtn=document.createElement\('button'\);
    uploadBtn.className='att-edit-upload';
    uploadBtn.textContent='+';
    uploadBtn.title='上传照片';
    uploadBtn.addEventListener\('click',\(\)=>{
      const input=document.createElement\('input'\);
      input.type='file'; input.accept='image/*,video/*,.mp4,.mov,.m4v,.webm'; input.multiple=true;
      input.addEventListener\('change',\(\)=>routeUploadPhotos\(ctx,input.files\)\);
      input.click\(\);
    }\);
    thumbs.appendChild\(uploadBtn\);
    photoRow.appendChild\(thumbs\);
    const hint=document.createElement\('div'\);
    hint.className='att-edit-hint';
    hint.textContent='支持多张照片/视频同时上传 · 视频仅限本机模式';
    photoRow.appendChild\(hint\);
    attEditPanel.appendChild\(photoRow\);

    attEditOverlay.classList.add\('show'\);
  }
  // 详情页旧入口 → canonical 编辑器（保持调用点兼容）
  function openAttEditPanel\(idx\){
    if\(!attDetailCity\) return;
    openRouteEditor\(attDetailCity.cityKey,idx,'detail'\);
  }
  function closeAttEditPanel\(\){
    attEditOverlay.classList.remove\('show'\);
    routeEditorCtx=null;
  }
  // 点击遮罩外区域关闭编辑面板
  attEditOverlay.addEventListener\('click',e=>{ if\(e.target===attEditOverlay\) closeAttEditPanel\(\); }\);
BLOCK_EOF)

